    module = TestModule()
    module.set("scrolling.width", 10)
    return module

def someEvent():
    class Event:
        def __init__(self):
            core.event.clear()
            self.id = "some event"
            self.called = 0
            self.call_args = []
            self.call_kwargs = []

        def callback(self, *args, **kwargs):
            self.called += 1
            if args:
                self.call_args.append(list(args))
            if kwargs:
                self.call_kwargs.append(kwargs)

    return Event()

