def probability_predictor():
    class TestGaussianPredictor:
        def predict(self, prior, control_input=None, timestamp=None, **kwargs):
            return GaussianStatePrediction(prior.state_vector + 1,
                                           prior.covar * 2, timestamp)
    return TestGaussianPredictor()

def probability_updater():
    class TestGaussianUpdater:
        def predict_measurement(self, state_prediction, measurement_model=None,
                                **kwargs):
            return GaussianMeasurementPrediction(state_prediction.state_vector,
                                                 state_prediction.covar,
                                                 state_prediction.timestamp)
    return TestGaussianUpdater()

def detector():
    class Detector(DetectionReader):

        @BufferedGenerator.generator_method
        def detections_gen(self):
            for i in range(-3, 4):
                detections = {Detection([[i], [50], [5000 + i*10]])}
                yield None, detections

    return Detector()

def groundtruth():
    class GroundTruth(GroundTruthReader):

        @BufferedGenerator.generator_method
        def groundtruth_paths_gen(self):
            path = GroundTruthPath()
            for i in range(-3, 4):
                path.append(GroundTruthState([[i], [50], [5000 + i*10]]))
                truths = {path}
                yield None, truths

    return GroundTruth()

def transition_model1():
    class TestTransitionModel:
        def function(self, state, noise, time_interval):
            return state.state_vector + time_interval.total_seconds()
    return TestTransitionModel()

def transition_model2():
    class TestTransitionModel:
        def function(self, state, noise, time_interval):
            return state.state_vector + 2*time_interval.total_seconds()
    return TestTransitionModel()

def measurement_model():
    class TestMeasurementModel:
        ndim_state = 4
        ndim_meas = 2

        @staticmethod
        def function(state, noise):
            matrix = np.array([[1, 0, 0, 0], [0, 0, 1, 0]])
            return matrix @ state.state_vector
    return TestMeasurementModel()

def sensor_model2():
    class TestSensor(Sensor):

        def measure(self, ground_truths):
            detections = set()
            for truth in ground_truths:
                detections.add(Detection(truth.state_vector, timestamp=truth.timestamp))
            return detections
    return TestSensor()

