def prevent_color():
    def uncolor(text, color):
        return text

    with contextlib.ExitStack() as ctx_stack:
        for ctx in [
            mock.patch(f'{module}.colorize', uncolor, create=True)
            for module in get_modules_from_package(detect_secrets)
        ]:
            ctx_stack.enter_context(ctx)

        yield

