def get_calcjob_node(clear_database_before_test, generate_calculation_node):
    """Return a calculation node with `Dict` output with default output label and the dictionary it contains."""
    node = generate_calculation_node(entry_point='aiida.calculations:templatereplacer').store()
    dictionary = {
        'key_one': 'val_one',
        'key_two': 'val_two',
    }

    results = Dict(dict=dictionary).store()
    results.add_incoming(node, link_type=LinkType.CREATE, link_label=node.process_class.spec().default_output_node)

    return node, dictionary

def reference_result():
    """Return reference results (for check)."""

    def inner(name):
        return os.path.join(os.path.dirname(__file__), 'reference_results', name)

    return inner

def xml_equal():
    """Check whether output and reference XML are identical."""

    def inner(test_file, reference_file):
        if not os.path.isfile(reference_file):
            shutil.copyfile(test_file, reference_file)
            raise ValueError('Reference file does not exist!')
        try:
            assert _flatten_xml(test_file) == _flatten_xml(reference_file)
        except AssertionError:
            print(Path(test_file.read_text()))
            raise

    return inner

