def upload_file(dev):
    def doit(data, pkt_len=2048):

        from hashlib import sha256
        import os

        for pos in range(0, len(data), pkt_len):
            v = dev.send_recv(CCProtocolPacker.upload(pos, len(data), data[pos:pos+pkt_len]))
            assert v == pos
            chk = dev.send_recv(CCProtocolPacker.sha256())
            assert chk == sha256(data[0:pos+pkt_len]).digest(), 'bad hash'
    return doit

def word_menu_entry(cap_menu, pick_menu_item):
    def doit(words):
        # do the massive drilling-down to pick a specific pass phrase
        assert len(words) in {1, 12, 18, 24}

        for word in words:
            while 1:
                menu = cap_menu()
                which = None
                for m in menu:
                    if '-' not in m:
                        if m == word:
                            which = m
                            break
                    else:
                        assert m[-1] == '-'
                        if m == word[0:len(m)-1]+'-':
                            which = m
                            break

                assert which, "cant find: " + word

                pick_menu_item(which)
                if '-' not in which: break

    return doit

def enter_complex(get_pp_sofar, need_keypress, pick_menu_item):
    def doit(target):
        # full entry mode
        # - just left to right here
        # - not testing case swap, because might remove that
        symbols = ' !"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~'

        pick_menu_item('Edit Phrase')

        for pos, d in enumerate(target):
            time.sleep(.01)      # required
            if d.isalpha():
                if pos != 0:        # A is already default first
                    need_keypress('1')

                if d.islower():
                    time.sleep(.01)      # required
                    need_keypress('1')

                cnt = ord(d.lower()) - ord('a')

            elif d.isdigit():
                need_keypress('2')
                if d == '0':
                    time.sleep(.01)      # required
                    need_keypress('8')
                    cnt = 0
                else:
                    cnt = ord(d) - ord('1')
            else:
                assert d in symbols
                if pos == 0:
                    need_keypress('3')

                cnt = symbols.find(d)

            for i in range(cnt):
                time.sleep(.01)      # required
                need_keypress('5')

            if pos != len(target)-1:
                time.sleep(.01)      # required
                need_keypress('9')

        time.sleep(0.01)      # required
        need_keypress('y')

    return doit

def assert_equals_stdout(capsys):
