    return should_equal

def server_key_fp():
    """Factory to return a key, old if so chosen."""
    def _server_key_fp(old: bool):
        for fp, data in rsa._server_keys.items():
            _, old_key = data
            if old_key == old:
                return fp

    return _server_key_fp

