def expected_large_values(self):
        num_vertices = 0
        num_faces = 0
        num_uvs = 0
        num_normals = 0
        num_materials = 0
        num_face_groups = 0
        with open(os.path.join(ROOT_DIR, "model.obj")) as f:
            for line in f.readlines():
                data = line.split()
                if len(data) == 0:
                    continue
                if data[0] == 'f':
                    num_faces += 1
                elif data[0] == 'v':
                    num_vertices += 1
                elif data[0] == 'vt':
                    num_uvs += 1
                elif data[0] == 'vn':
                    num_normals += 1
                elif data[0] == 'usemtl':
                    num_face_groups += 1
                elif data[0] == 'mtllib':
                    num_materials += _get_num_mtl(os.path.join(ROOT_DIR, data[1]))
        return {'num_vertices': num_vertices,
                'num_faces': num_faces,
                'num_uvs': num_uvs,
                'num_normals': num_normals,
                'num_materials': num_materials,
                'num_face_groups': num_face_groups}

