def setUp(self):
        self.state_keys = dir(states)
        self.tc_dump = {}
        for key in self.state_keys:
            if key.startswith("__"):
                continue
            if key.startswith("_"):
                value = getattr(states, key)
                if callable(value):
                    continue
                self.tc_dump[key] = value
        couler._cleanup()

def tearDown(self):
        couler._cleanup()
        for key in self.state_keys:
            if key.startswith("__"):
                continue
            if key.startswith("_"):
                value = getattr(states, key)
                if callable(value):
                    continue
                self.assertEqual(
                    value, self.tc_dump[key], msg="state not cleanup:%s" % key
                )

