def example_graph_schema():
    def create_schema(aa=1, ab=1, ba=1, bb=1):
        # graph schema
        schema = {"A": [], "B": []}
        for ii in range(aa):
            schema["A"].append(EdgeType("A", "a%d" % ii, "A"))
        for ii in range(ab):
            schema["A"].append(EdgeType("A", "ab%d" % ii, "B"))
        for ii in range(ba):
            schema["B"].append(EdgeType("B", "ab%d" % ii, "A"))
        for ii in range(bb):
            schema["B"].append(EdgeType("B", "b%d" % ii, "B"))

        return GraphSchema(
            is_directed=False,
            node_types=sorted(schema.keys()),
            edge_types=sorted(set(it.chain(*schema.values()))),
            schema=schema,
        )

    return create_schema

def temporal_graph():
    nodes = [1, 2, 3, 4, 5, 6]
    edges = [(1, 2, 5), (2, 3, 2), (2, 4, 10), (4, 5, 3), (4, 6, 12)]
    edge_cols = ["source", "target", "weight"]
    return StellarGraph(
        nodes=pd.DataFrame(index=nodes), edges=pd.DataFrame(edges, columns=edge_cols),
    )

def arange_graph(request):
    shape = (3, 7, 11) if request.param == "multivariate" else (3, 7)
    total_elems = np.product(shape)
    nodes = IndexedArray(
        np.arange(total_elems).reshape(shape) / total_elems, index=["a", "b", "c"]
    )
    edges = pd.DataFrame({"source": ["a", "b"], "target": ["b", "c"]})
    return StellarGraph(nodes, edges)

def line_graph() -> StellarGraph:
    nodes = node_features()
    edges = pd.DataFrame([(i, i + 1) for i in range(9)], columns=["source", "target"])
    return StellarGraph(nodes, edges)

def barbell():
    graph = nx.barbell_graph(m1=10, m2=11)
    for i, (src, tgt) in enumerate(graph.edges):
        graph[src][tgt]["weight"] = (i + 1) / 5
    return StellarGraph.from_networkx(graph)

def make_api(batch_mode):
    def _make_api(input_adapter, user_func):
        if not input_adapter.BATCH_MODE_SUPPORTED and batch_mode:
            pytest.skip()
        if not input_adapter.SINGLE_MODE_SUPPORTED and not batch_mode:
            pytest.skip()
        return InferenceAPI(
            None,
            "test_api",
            "",
            input_adapter=input_adapter,
            user_func=user_func,
            output_adapter=DefaultOutput(),
            batch=batch_mode,
        )

    return _make_api

