def fastai_random_data_run_with_callback(iris_data, fit_variant, manual_run, callback, patience):
    # pylint: disable=unused-argument
    mlflow.fastai.autolog()

    model = fastai_model(iris_data)

    callbacks = []
    if callback == "early":
        callback = EarlyStoppingCallback(learn=model, patience=patience, min_delta=MIN_DELTA)
        callbacks.append(callback)

    if fit_variant == "fit_one_cycle":
        model.fit_one_cycle(NUM_EPOCHS, callbacks=callbacks)
    else:
        model.fit(NUM_EPOCHS, callbacks=callbacks)

    client = mlflow.tracking.MlflowClient()
    return model, client.get_run(client.list_run_infos(experiment_id="0")[0].run_id)

def h2o_iris_model():
    h2o.init()
    iris = datasets.load_iris()
    data = h2o.H2OFrame(
        {
            "feature1": list(iris.data[:, 0]),
            "feature2": list(iris.data[:, 1]),
            "target": list(map(lambda i: "Flower %d" % i, iris.target)),
        }
    )
    train, test = data.split_frame(ratios=[0.7])  # pylint: disable=unbalanced-tuple-unpacking

    h2o_gbm = H2OGradientBoostingEstimator(ntrees=10, max_depth=6)
    h2o_gbm.train(["feature1", "feature2"], "target", training_frame=train)
    return ModelWithData(model=h2o_gbm, inference_data=test)

def custom_layer():
    class MyDense(Layer):
        def __init__(self, output_dim, **kwargs):
            self.output_dim = output_dim
            super().__init__(**kwargs)

        def build(self, input_shape):
            # pylint: disable=attribute-defined-outside-init
            self.kernel = self.add_weight(
                name="kernel",
                shape=(input_shape[1], self.output_dim),
                initializer="uniform",
                trainable=True,
            )
            super().build(input_shape)

        def call(self, x):
            # pylint: disable=arguments-differ
            return K.dot(x, self.kernel)

        def compute_output_shape(self, input_shape):
            return (input_shape[0], self.output_dim)

        def get_config(self):
            return {"output_dim": self.output_dim}

    return MyDense

