def special_reg(request):
    if request.param['mode'] == 'quality':
        X, y = fetch_california_housing(return_X_y=True)
    else:
        X, y = make_regression(n_samples=request.param['n_samples'],
                               n_features=request.param['n_features'],
                               n_informative=request.param['n_informative'],
                               random_state=123)
    return X, y

def pgconn(dsn):
    """Return a PGconn connection open to `--test-dsn`."""
    from psycopg3 import pq

    conn = pq.PGconn.connect(dsn.encode("utf8"))
    if conn.status != pq.ConnStatus.OK:
        pytest.fail(
            f"bad connection: {conn.error_message.decode('utf8', 'replace')}"
        )
    yield conn
    conn.finish()

def libpq():
    """Return a ctypes wrapper to access the libpq."""
    import ctypes.util

    try:
        # Not available when testing the binary package
        if sys.platform == "win32":
            libname = ctypes.util.find_library("libpq.dll")
        else:
            libname = ctypes.util.find_library("pq")
        assert libname, "libpq libname not found"
        return ctypes.pydll.LoadLibrary(libname)
    except Exception as e:
        from psycopg3 import pq

        if pq.__impl__ == "binary":
            pytest.skip(f"can't load libpq for testing: {e}")
        else:
            raise

def _execmany(svcconn):
    cur = svcconn.cursor()
    cur.execute(
        """
        drop table if exists execmany;
        create table execmany (id serial primary key, num integer, data text)
        """
    )

