        not_editable = Field.text(initial='Some non-editable text', editable=False)
        multi_choice_field = Field.multi_choice(choices=['a', 'b', 'c', 'd'], required=False)

        class Meta:
            @staticmethod
            def actions__submit__post_handler(form, **_):
                pass  # pragma: no cover

    return MyTestForm

