def gather(request, gather_simple, gather_alternate):
    """Parametrize the gather fixtures"""
    type = request.param
    if type == 'gather_simple':
        return gather_simple
    elif type == 'gather_alternate':
        return gather_alternate
    else:
        raise ValueError(f'Unknown gather fixture: "{type}"')

def run_exp_to_source():
    inputs = [
        MultiSlitModel(f)
        for f in helpers.INPUT_FILES
    ]
    outputs = exp_to_source(inputs)
    yield inputs, outputs
    for model in inputs:
        model.close()

def apcorr_instance(inputs):
    dm, table = inputs
    apcorr = select_apcorr(dm)

    if dm.meta.instrument.name == 'NIRSPEC' and 'FIXEDSLIT' in dm.meta.exposure.type:
        return apcorr(dm, table, 'pixels', slit='S200A1')

    return apcorr(dm, table, 'pixels')

