def node_control_util_patched(monkeypatch, request):
    def pkg_version(pkg_name, version):
        return (
            PkgDebianVersion(
                pkg_name or some_pkg_name, version) if version else None
        )

    def pkg_info(pkg_name, version, deps):
        def wrapped(*x):
            return (pkg_version(pkg_name, version), deps)
        return wrapped

    def latest_pkg_ver(pkg_name, version):
        def wrapped(*x, **y):
            return pkg_version(pkg_name, version)
        return wrapped

    marker = request.node.get_marker('pkg_info')
    if marker:
        assert len(marker.args) > 1
        monkeypatch.setattr(
            NodeControlUtil, 'curr_pkg_info',
            pkg_info(
                marker.kwargs.get('pkg_name'),
                marker.args[0],
                marker.args[1]
            )
        )

    marker = request.node.get_marker('latest_pkg_ver')
    if marker:
        assert len(marker.args) > 0
        monkeypatch.setattr(
            NodeControlUtil, 'get_latest_pkg_version',
            latest_pkg_ver(
                marker.kwargs.get('pkg_name'),
                marker.args[0]
            )
        )

def read_txn_and_get_latest_info(looper, sdk_pool_handle,
                                 sdk_wallet_client, node):
    _, did = sdk_wallet_client

    def read_wrapped(txn_type):
        if txn_type == GET_NYM:
            makeGetNymRequest(looper, sdk_pool_handle, sdk_wallet_client, did)
        elif txn_type == GET_SCHEMA:
            makeGetSchemaRequest(looper, sdk_pool_handle, sdk_wallet_client, did)
        elif txn_type == GET_ATTR:
            makeGetAttrRequest(looper, sdk_pool_handle, sdk_wallet_client, did, "attrName")
        elif txn_type == GET_CLAIM_DEF:
            makeGetClaimDefRequest(looper, sdk_pool_handle, sdk_wallet_client)
        else:
            assert False, "unexpected txn type {}".format(txn_type)
        return node._info_tool.info

    return read_wrapped

def ec2_resources(request, regions, ec2):

    def gen_params(group_suffix=None, key_name_suffix=None,
                   security_group_suffix=None):

        def _random(N=7):
            return ''.join(random.choice(string.ascii_uppercase + string.digits)
                           for _ in range(N))

        return InstanceParams(
            project='Indy-PA-dev',
            add_tags={'Purpose': 'Test Pool Automation'},
            namespace='test_stateful_set',
            group="group_{}"
                  .format(group_suffix if group_suffix
                          else _random()),
            key_name="test_stateful_set_key_{}"
                     .format(key_name_suffix if key_name_suffix
                             else _random()),
            security_group="test_stateful_set_security_group_{}"
                           .format(security_group_suffix
                                   if security_group_suffix
                                   else _random()),
            type_name='t2.micro',
            # TODO docs
            market_spot=(request.config.getoption("--market-type") == 'spot'),
            spot_max_price=None,
            # TODO docs
            ebs_volume_size=9,
            ebs_volume_type='gp2',
        )

    def manage_key_pair(ec2, present, params):
        count = 0
        for key in ec2.key_pairs.all():
            if key.key_name != params.key_name:
                continue
            if present and count == 0:
                count = 1
            else:
                key.delete()
        if present and count == 0:
            ec2.create_key_pair(KeyName=params.key_name)

    def manage_security_group(ec2, present, params):
        count = 0
        for sgroup in ec2.security_groups.all():
            if sgroup.group_name != params.security_group:
                continue
            if present and count == 0:
                count = 1
            else:
                sgroup.delete()
        if present and count == 0:
            sg = ec2.create_security_group(
                GroupName=params.security_group,
                Description='Test security group')
            sg.create_tags(Tags=[
                {'Key': 'Name', 'Value': "{}-{}-{}"
                    .format(params.project,
                            params.namespace,
                            params.group)},
                {'Key': 'Project', 'Value': params.project},
                {'Key': 'Namespace', 'Value': params.namespace},
                {'Key': 'Group', 'Value': params.group}])

    params = gen_params(
        group_suffix=request.node.name,
        key_name_suffix=request.node.name,
        security_group_suffix=request.node.name
    )

    for rc in ec2:
        manage_key_pair(rc, True, params)
        manage_security_group(rc, True, params)
    yield params

    terminator = AwsEC2Terminator()
    for region, rc in zip(regions, ec2):
        for inst in find_instances(
                rc, params.project, params.namespace, params.group):
            terminator.terminate(inst, region)
    terminator.wait(False)

    for rc in ec2:
        manage_key_pair(rc, False, params)
        manage_security_group(rc, False, params)

