def authorized_cookies(loop, aiohttp_client):
    async def get_cookie():
        r = await aiohttp_client.post('/enter', allow_redirects=False, data=dict(username='admin', password='admin'))
        return r.cookies
    return loop.run_until_complete(get_cookie())

