def new_subscription_with_activity(new_subscription, profile):
    kwargs = {
        'created_on': datetime(2018, 12, 29, 14, 22, 35, tzinfo=UTC),
        'profile': profile,
        'subscription': new_subscription,
        'activity_type': 'new_grant_subscription',
